#!/usr/bin/env python3
"""Revision-scoped lease census and causal application service census.

Discovery evidence is lease scoped: internal clean sets hold low targets that
positively echoed themselves, external clean sets hold other responders, and a
canary self echo quarantines its whole lease.  Application rows only count when
their lease is usable, their target holds a clean role, and that role's earliest
causal witness is not later than the row's event.
"""
from ledger import Ledger
from protocols import cached_signature

ECHO, ERROR, TIMEOUT = 0, 1, 2
ICMP, APP, TOMB = 0, 1, 2


class LeaseEvidence:
    """Mutable per-query discovery accumulators for a single lease."""

    __slots__ = ('internal', 'external', 'alias', 'witness_internal',
                 'witness_external')

    def __init__(self):
        self.internal = set()
        self.external = set()
        self.alias = False
        self.witness_internal = {}
        self.witness_external = {}

    def support(self, role, address, moment):
        table = self.witness_internal if role == ICMP else self.witness_external
        previous = table.get(address)
        if previous is None or moment < previous:
            table[address] = moment


def empty_services(service_order):
    return {name: {'internal_open': set(), 'internal_closed': set(),
                   'external_open': set(), 'external_closed': set(),
                   'protocol_errors': 0} for name in service_order}


def build(context, records, low):
    """Return (snapshots, request activity) for every query in increasing order."""
    leases = context['leases']
    services = context['services']
    service_order = context['service_order']
    kinds = {name: services[name] for name in services}
    ledger = Ledger(records)
    requests_by_query = {moment: [] for moment in context['queries']}
    for row in context['requests'].values():
        requests_by_query[row['at']].append(row)

    snapshots = []
    activity = {}
    for moment in context['queries']:
        counts, live = ledger.at(moment)
        evidence = {name: LeaseEvidence() for name in leases}

        applications = []
        for detail in live:
            if detail[ICMP] != ICMP:
                if detail[ICMP] == APP:
                    applications.append(detail)
                continue
            _, lease, event, target, responder, result, is_canary = detail
            state = evidence.get(lease)
            if state is None:
                continue
            if is_canary:
                # Only a positive canary self echo marks the lease aliased.
                if result == ECHO and responder == target:
                    state.alias = True
                continue
            if result == TIMEOUT:
                continue
            if result == ECHO and responder == target:
                state.internal.add(responder)
                state.support(ICMP, responder, event)
            else:
                state.external.add(responder)
                state.support(APP, responder, event)

        clean = {}
        quarantined = {}
        for lease, state in evidence.items():
            row = leases[lease]
            active = row['start'] <= moment < row['end']
            conflicts = state.internal & state.external if active else set()
            if not active:
                clean[lease] = ('inactive', set(), set(), conflicts, state)
            elif state.alias:
                clean[lease] = ('alias', set(), set(), conflicts, state)
            elif conflicts:
                clean[lease] = ('conflict', set(), set(), conflicts, state)
            else:
                clean[lease] = ('usable', state.internal, state.external, conflicts, state)

        groups = {}
        unbound = 0
        for detail in applications:
            _, lease, event, target, service, attempt, result, payload = detail
            entry = clean.get(lease)
            if entry is None or entry[0] != 'usable':
                unbound += 1
                continue
            state = entry[4]
            if target in entry[1]:
                role = ICMP
                witness = state.witness_internal.get(target)
            elif target in entry[2]:
                role = APP
                witness = state.witness_external.get(target)
            else:
                role = None
                witness = None
            if role is None or witness is None or witness > event:
                unbound += 1
                continue
            key = (lease, target, service)
            group = groups.get(key)
            if group is None:
                group = groups[key] = [attempt, role, {}, 0, 0, 0]
            if attempt > group[0]:
                group[0] = attempt
                group[2] = {}
                group[3] = group[4] = group[5] = 0
            if attempt != group[0]:
                continue
            if result == ECHO:          # open
                parsed = cached_signature(kinds[service], payload)
                if parsed is None:
                    group[3] += 1
                else:
                    group[2][parsed] = group[2].get(parsed, 0) + 1
            elif result == ERROR:       # closed
                group[4] += 1
            else:
                group[5] += 1

        buckets = {}
        for key, group in groups.items():
            lease, target, service = key
            entry = clean[lease]
            bucket = buckets.get((lease, service))
            if bucket is None:
                bucket = buckets[(lease, service)] = empty_services(service_order)
            report = bucket[service]
            total = group[3] + group[4] + group[5] + sum(group[2].values())
            report['protocol_errors'] += group[3]
            if group[4] == total:
                status = 'closed'
            elif (not group[3] and not group[5] and group[4] == 0
                  and len(group[2]) == 1):
                status = 'open'
            else:
                status = None
            if status is None:
                continue
            prefix = 'internal' if group[1] == ICMP else 'external'
            report[prefix + '_' + status].add(target)

        lease_rows = []
        known = {}
        for name in sorted(leases):
            state_kind, internal, external, conflicts, state = clean[name]
            if state_kind == 'usable':
                unresolved = low[name] - internal - external
            elif state_kind == 'inactive':
                unresolved = set()
            else:
                unresolved = set(low[name])
            reports = buckets.get((name, None))
            services_out = []
            for service in service_order:
                if state_kind == 'usable':
                    report = (buckets.get((name, service)) or
                              empty_services(service_order))[service]
                    internal_open = report['internal_open']
                    internal_closed = report['internal_closed']
                    external_closed = report['external_closed']
                    if external and len(external_closed) == len(external):
                        internal_only = internal_open
                    else:
                        internal_only = set()
                    errors = report['protocol_errors']
                    known[(name, service)] = internal_open | internal_closed
                else:
                    internal_open = internal_closed = set()
                    external_open = external_closed = internal_only = set()
                    errors = 0
                services_out.append({'id': service,
                                     'internal_open': _text(internal_open),
                                     'internal_closed': _text(internal_closed),
                                     'external_open': _text(external_open),
                                     'external_closed': _text(external_closed),
                                     'internal_only': _text(internal_only),
                                     'protocol_errors': errors})
            lease_rows.append({'lease': name, 'state': state_kind,
                               'conflicts': _text(conflicts),
                               'internal': _text(internal),
                               'external': _text(external),
                               'unresolved': _text(unresolved),
                               'services': services_out})

        for row in requests_by_query[moment]:
            entry = clean.get(row['lease'])
            yes = bool(entry is not None and entry[0] == 'usable'
                       and row['address'] in entry[1]
                       and row['address'] not in known.get((row['lease'], row['service']),
                                                           frozenset()))
            activity[row['id']] = yes

        snapshots.append({'at': moment, 'ledger': counts,
                          'unbound_applications': unbound, 'leases': lease_rows})
    return snapshots, activity


def _text(values):
    from common import addresses
    return addresses(values)
